content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-04-focus-020

=== 用户原始指令 (query.txt) ===
我想弄个带浅色底色的白噪音专注卡片，中间是个环形的进度比例盘，显示动态的剩余时间25分钟，底部用【音1】【音2】【音3】这种字符图标横向排列好几个不同氛围的音乐选项，配上时间流逝的深色渐变，点一下就能跳到音乐应用里直接播放对应的助眠白噪音歌单。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "我想弄个带浅色底色的白噪音专注卡片，中间是个环形的进度比例盘，显示动态的剩余时间25分钟，底部用【音1】【音2】【音3】这种字符图标横向排列好几个不同氛围的音乐选项，配上时间流逝的深色渐变，点一下就能跳到音乐应用里直接播放对应的助眠白噪音歌单。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hwmusic://com.huawei.hmsapp.music/showMusicList?code=a001&type=4"
      }
    }
  ],
  "dataModelSchema": {
    "focus": {
      "title": {
        "type": "string",
        "description": "卡片标题，表达当前是白噪音专注场景。",
        "sampleValue": "白噪音专注"
      },
      "temporalText": {
        "type": "string",
        "description": "时间流逝氛围提示短文案。",
        "sampleValue": "时间流逝"
      },
      "modeText": {
        "type": "string",
        "description": "当前播放或专注氛围的主标签。",
        "sampleValue": "白噪音"
      },
      "captionText": {
        "type": "string",
        "description": "当前白噪音氛围的辅助说明。",
        "sampleValue": "雨声助眠"
      },
      "remainingText": {
        "type": "string",
        "description": "动态剩余时间展示文本。",
        "sampleValue": "25分钟"
      },
      "progressValue": {
        "type": "number",
        "description": "专注计时已流逝进度值，用于环形比例盘。",
        "sampleValue": 5
      },
      "progressTotal": {
        "type": "number",
        "description": "本次专注计时总时长，用于环形比例盘总量。",
        "sampleValue": 30
      },
      "elapsedText": {
        "type": "string",
        "description": "已流逝时间展示文本。",
        "sampleValue": "5分"
      },
      "totalText": {
        "type": "string",
        "description": "本轮白噪音专注总时长展示文本。",
        "sampleValue": "30分"
      }
    },
    "music": {
      "option1Glyph": {
        "type": "string",
        "description": "第一个白噪音氛围入口的字符图标。",
        "sampleValue": "【音1】"
      },
      "option2Glyph": {
        "type": "string",
        "description": "第二个白噪音氛围入口的字符图标。",
        "sampleValue": "【音2】"
      },
      "option3Glyph": {
        "type": "string",
        "description": "第三个白噪音氛围入口的字符图标。",
        "sampleValue": "【音3】"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_focus.png",
      "description": "专注图标，适合用于专注模式场景的身份识别或轻量视觉锚点。"
    },
    {
      "src": "resources/base/media/music_fill.svg",
      "description": "音乐音符实心图标，适合用于音乐播放卡片、音频功能入口或歌单展示。"
    }
  ]
}

